# 1. Create proper directory structure
mkdir -p examples
mkdir -p docs
mkdir -p bin

# 2. Create example C programs
cat > examples/hello.c << 'EOF'
#include <stdio.h>

int main() {
  printf("Hello, World!\n");
  return 0;
}
EOF

cat > examples/factorial.c << 'EOF'
#include <stdio.h>

int factorial(int n) {
  if (n <= 1) return 1;
  return n * factorial(n - 1);
}

int main() {
  printf("5! = %d\n", factorial(5));
  return 0;
}
EOF

cat > examples/fibonacci.c << 'EOF'
#include <stdio.h>

int fib(int n) {
  if (n <= 1) return n;
  return fib(n - 1) + fib(n - 2);
}

int main() {
  for (int i = 0; i < 10; i++) {
    printf("fib(%d) = %d\n", i, fib(i));
  }
  return 0;
}
EOF

cat > examples/array.c << 'EOF'
#include <stdio.h>

int main() {
  int arr[5] = {1, 2, 3, 4, 5};
  int sum = 0;

  for (int i = 0; i < 5; i++) {
    sum += arr[i];
  }

  printf("Sum: %d\n", sum);
  printf("Average: %d\n", sum / 5);
  return 0;
}
EOF

